118|static int
119|process_file(const char* in_path, FILE* in, FILE* out)
120|{
121|    size_t n;
122|    struct membuffer buf_in = {0};
123|    struct membuffer buf_out = {0};
124|    int ret = -1;
125|    clock_t t0, t1;
126|    unsigned p_flags = parser_flags;
127|    unsigned r_flags = renderer_flags;
128|
129|    membuf_init(&buf_in, 32 * 1024);
130|
131|    /* Read the input file into a buffer. */
132|    while(1) {
133|        if(buf_in.size >= buf_in.asize)
134|            membuf_grow(&buf_in, buf_in.asize + buf_in.asize / 2);
135|
136|        n = fread(buf_in.data + buf_in.size, 1, buf_in.asize - buf_in.size, in);
137|        if(n == 0)
138|            break;
139|        buf_in.size += n;
140|    }
141|
142|    /* Input size is good estimation of output size. Add some more reserve to
143|     * deal with the HTML header/footer and tags. */
144|    membuf_init(&buf_out, (MD_SIZE)(buf_in.size + buf_in.size/8 + 64));
145|
146|    /* Special mode for reproduce test case found with fuzzing a tool.
147|     * We assume file format as produced by test/fuzzers/fuzz-mdhtml.c. */
148|    if(want_replay_fuzz) {
149|        if(buf_in.size < 2 * sizeof(unsigned)) {
150|            fprintf(stderr, "File %s isn't valid fuzz test case.\n", in_path);
151|            ret = -1;
152|            goto out;
153|        }
154|
155|        /* Override parser and renderer flags with those form the test case. */
156|        p_flags = ((unsigned*)buf_in.data)[0];
157|        r_flags = ((unsigned*)buf_in.data)[1];
158|
159|        /* And get rid of them from the text input to the parser. */
160|        memmove(buf_in.data, buf_in.data + 2 * sizeof(unsigned),
161|                    buf_in.size - 2 * sizeof(unsigned));
162|        buf_in.size -= 2 * sizeof(unsigned);
163|
164|        /* Zero the tail we have moved the contents from.
165|         * It helps in debugging if make it actually a zero-terminated string. */
166|        memset(buf_in.data + buf_in.size, 0, 2 * sizeof(unsigned));
167|    }
168|
169|    /* Parse the document. This shall call our callbacks provided via the
170|     * md_renderer_t structure. */
171|    t0 = clock();
172|
173|    ret = md_html(buf_in.data, (MD_SIZE)buf_in.size, process_output,
174|                (void*) &buf_out, p_flags, r_flags);
175|
176|    t1 = clock();
177|    if(ret != 0) {
178|        fprintf(stderr, "Parsing failed.\n");
179|        goto out;
180|    }
181|
182|    /* Write down the document in the HTML format. */
183|    if(want_fullhtml) {
184|        if(want_xhtml) {
185|            fprintf(out, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
186|            fprintf(out, "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" "
187|                            "\"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
188|            fprintf(out, "<html xmlns=\"http://www.w3.org/1999/xhtml\">\n");
189|        } else {
190|            fprintf(out, "<!DOCTYPE html>\n");
191|            fprintf(out, "<html>\n");
192|        }
193|        fprintf(out, "<head>\n");
194|        fprintf(out, "<title>%s</title>\n", html_title ? html_title : "");
195|        fprintf(out, "<meta name=\"generator\" content=\"md2html\"%s>\n", want_xhtml ? " /" : "");
196|#if !defined MD4C_USE_ASCII && !defined MD4C_USE_UTF16
197|        fprintf(out, "<meta charset=\"UTF-8\"%s>\n", want_xhtml ? " /" : "");
198|#endif
199|        if(css_path != NULL) {
200|            fprintf(out, "<link rel=\"stylesheet\" href=\"%s\"%s>\n", css_path, want_xhtml ? " /" : "");
201|        }
202|        fprintf(out, "</head>\n");
203|        fprintf(out, "<body>\n");
204|    }
205|
206|    fwrite(buf_out.data, 1, buf_out.size, out);
207|
208|    if(want_fullhtml) {
209|        fprintf(out, "</body>\n");
210|        fprintf(out, "</html>\n");
211|    }
212|
213|    if(want_stat) {
214|        if(t0 != (clock_t)-1  &&  t1 != (clock_t)-1) {
215|            double elapsed = (double)(t1 - t0) / CLOCKS_PER_SEC;
216|            if (elapsed < 1)
217|                fprintf(stderr, "Time spent on parsing: %7.2f ms.\n", elapsed*1e3);
218|            else
219|                fprintf(stderr, "Time spent on parsing: %6.3f s.\n", elapsed);
220|        }
221|    }
222|
223|    /* Success if we have reached here. */
224|    ret = 0;
225|
226|out:
227|    membuf_fini(&buf_in);
228|    membuf_fini(&buf_out);
229|
230|    return ret;
231|}

