505|static int
506|text_callback(MD_TEXTTYPE type, const MD_CHAR* text, MD_SIZE size, void* userdata)
507|{
508|    MD_HTML* r = (MD_HTML*) userdata;
509|
510|    switch(type) {
511|        case MD_TEXT_NULLCHAR:  render_utf8_codepoint(r, 0x0000, render_verbatim); break;
512|        case MD_TEXT_BR:        RENDER_VERBATIM(r, (r->image_nesting_level == 0
513|                                        ? ((r->flags & MD_HTML_FLAG_XHTML) ? "<br />\n" : "<br>\n")
514|                                        : " "));
515|                                break;
516|        case MD_TEXT_SOFTBR:    RENDER_VERBATIM(r, (r->image_nesting_level == 0 ? "\n" : " ")); break;
517|        case MD_TEXT_HTML:      render_verbatim(r, text, size); break;
518|        case MD_TEXT_ENTITY:    render_entity(r, text, size, render_html_escaped); break;
519|        default:                render_html_escaped(r, text, size); break;
520|    }
521|
522|    return 0;
523|}

